    /// <summary>
    /// Adds gifts to the beginning of a previously created collection. If the collection is owned by a channel chat, then requires can_post_messages administrator right in the channel chat. Returns the changed collection
    /// </summary>
    public Task<TdLib.TdApi.Objects.GiftCollection> AddGiftCollectionGiftsAsync(MessageSender ownerId = default, int collectionId = default, string[] receivedGiftIds = default)
    {

           using var activity =  StartCallActivity("AddGiftCollectionGiftsAsync", typeof(AddGiftCollectionGifts).FullName ?? "AddGiftCollectionGiftsAsync");

           try
           {
             return client.AddGiftCollectionGiftsAsync(ownerId, collectionId, receivedGiftIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
